import numpy as np, itertools
lines=open('opt1.xyz').read().split('\n')
at=[l.split() for l in lines[2:] if l.strip()]
P=np.array([[float(x) for x in a[1:4]] for a in at])
E=[a[0] for a in at]
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'Cl':1.02,'Cu':1.32}
found=set()
for i,j in itertools.combinations(range(len(P)),2):
    d=np.linalg.norm(P[i]-P[j])
    if d < cov[E[i]]+cov[E[j]]+0.45: found.add((i,j))
expected=[(0,1),(0,2),(0,5),(0,16),(0,24),(2,3),(3,4),(5,6),(6,7),(7,8),(8,9),(9,10),(10,11),(11,12),(12,13),(13,8),(11,14),(6,15),(15,16),(16,17),(17,18),(18,19),(19,20),(20,21),(21,22),(22,23),(23,18),(19,24)]
for b in expected:
    if b not in found and (b[1],b[0]) not in found: print('MISSING',b,E[b[0]],E[b[1]], round(np.linalg.norm(P[b[0]]-P[b[1]]),3))
# H bonding check
for i in range(25,43):
    ds=sorted([(np.linalg.norm(P[i]-P[j]),j) for j in range(25) if j!=i])[:1]
    print(i,E[i],'nearest heavy',ds[0][1],E[ds[0][1]],round(ds[0][0],3))
